/**
 * Assets for the share card, inlined as base64.
 *
 * They are embedded rather than read from disk or fetched because neither
 * survives contact with a serverless build: `fetch()` refuses the file:// URL
 * that import.meta.url produces on the node runtime, and a binary sitting
 * beside the route is not reliably traced into the function bundle — both
 * showed up as a 500 in production rather than a missing image.
 *
 * Fonts are Lato 400 and 900 (AIBP's secondary face), woff because that is
 * what Satori reads. Together the three come to about 73KB of source, which
 * buys a share card with no runtime dependency on anything at all.
 */

export const LOGO = 'data:image/png;base64,';

export const LATO_400 = Buffer.from('', 'base64');
export const LATO_900 = Buffer.from('', 'base64');
